32	func TestInstallHooks_FreshRepo(t *testing.T) {
33		repo := repoDir(t)
34		a := New()
35	
36		if a.AreHooksInstalled() {
37			t.Error("hooks reported installed in a fresh repo")
38		}
39	
40		n, err := a.InstallHooks(false, false)
41		if err != nil {
42			t.Fatalf("InstallHooks: %v", err)
43		}
44		if n != 1 {
45			t.Errorf("InstallHooks returned %d, want 1", n)
46		}
47		if !a.AreHooksInstalled() {
48			t.Error("hooks not reported installed after install")
49		}
50	
51		data, err := os.ReadFile(filepath.Join(repo, aiderConfigFile))
52		if err != nil {
53			t.Fatalf("read config: %v", err)
54		}
55		content := string(data)
56	
57		// notifications: true is not optional. IO.ring_bell guards on
58		// `self.bell_on_next_input and self.notifications` (io.py:1090), so the
59		// command alone is a silent no-op that captures nothing.
60		if !strings.Contains(content, "notifications: true") {
61			t.Error("config is missing `notifications: true` — the command alone is a silent no-op")
62		}
63		if !strings.Contains(content, notificationCommand) {
64			t.Errorf("config is missing the notification command:\n%s", content)
65		}
66		// The echo is load-bearing: Entire's bridge rejects an empty stdin read
67		// before the plugin runs, which aider would show the user every turn.
68		if !strings.HasPrefix(notificationCommand, "echo {}") {
69			t.Error("notification command must feed stdin; Entire's bridge rejects an empty read")
70		}
71		// Hook commands must name the entire binary via PATH, never a path inside
72		// the working tree — this file is commonly committed.
73		if strings.Contains(content, "..") || strings.Contains(content, "./entire") {
74			t.Errorf("notification command must not reference a path in the working tree:\n%s", content)
75		}
76		for _, rel := range []string{transcriptRel, llmHistoryRel, inputHistRel} {
77			if !strings.Contains(content, rel) {
78				t.Errorf("config is missing redirect for %s", rel)
79			}
80		}
